let buffer = Buffer.alloc(0);
for await (const chunk of process.stdin) {
  buffer = Buffer.concat([buffer, chunk]);
  while (buffer.includes('\r\n\r\n')) {
    const bodyStart = buffer.indexOf('\r\n\r\n') + 4;
    const length = Number(
      /Content-Length: (\d+)/i.exec(buffer.subarray(0, bodyStart).toString())[1],
    );
    if (buffer.length < bodyStart + length) break;
    const { id, method, params } = JSON.parse(
      buffer.subarray(bodyStart, bodyStart + length),
    );
    buffer = buffer.subarray(bodyStart + length);
    let result = {};
    if (method === 'initialize') {
      result = { positionEncoding: 'utf-8', diagnosticSource: 'test-mapper' };
    } else if (method === 'transform') {
      result = {
        text: `export default ${JSON.stringify(params.content.trim())};`,
        extension: '.ts',
      };
    }
    const body = JSON.stringify({ jsonrpc: '2.0', id, result });
    process.stdout.write(
      `Content-Length: ${Buffer.byteLength(body)}\r\n\r\n${body}`,
    );
  }
}
